<?php
namespace App\Console\Commands; use App\Models\IntegrationDelivery; use App\Models\Ticket; use App\Services\DashboardSummary; use Illuminate\Console\Command; use Illuminate\Database\QueryException; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\DB;
final class ResilienceLab extends Command { protected $signature='lab:resilience {scenario : cache|queue|race|performance|incident}'; protected $description='Deterministic Part VI evidence harness'; public function handle(DashboardSummary $summary):int{$scenario=$this->argument('scenario');return match($scenario){'cache'=>$this->cache($summary),'queue'=>$this->queue(),'race'=>$this->race(),'performance'=>$this->performance($summary),'incident'=>$this->incident(),default=>$this->invalid()};}
 private function cache(DashboardSummary $summary):int{$org=1;Cache::forget(DashboardSummary::key($org));$this->line('miss '.json_encode($summary->get($org)));$this->line('hit  '.json_encode($summary->get($org)));$before=Cache::get(DashboardSummary::key($org));Ticket::where('organization_id',$org)->first()?->update(['status'=>'closed']);$this->line('database changed; cached copy is stale '.json_encode($before));$summary->forget($org);$this->line('repaired '.json_encode($summary->get($org)));return self::SUCCESS;}
 private function queue():int{$this->table(['state','count'],[['ready',DB::table('jobs')->whereNull('reserved_at')->count()],['reserved',DB::table('jobs')->whereNotNull('reserved_at')->count()],['failed',DB::table('failed_jobs')->count()]]);return self::SUCCESS;}
 private function race():int{$ticket=Ticket::firstOrFail();$id=(string)\Illuminate\Support\Str::uuid();$values=['organization_id'=>$ticket->organization_id,'ticket_id'=>$ticket->id,'job_id'=>$id,'correlation_id'=>'race-lab','created_at'=>now(),'updated_at'=>now()];$this->line('A: check absent');$this->line('B: check absent');DB::table('integration_deliveries')->insert($values);$this->line('A: insert succeeds');try{DB::table('integration_deliveries')->insert($values);$this->error('B unexpectedly inserted');return self::FAILURE;}catch(QueryException){$this->line('B: unique constraint rejects duplicate; one effect remains');}return self::SUCCESS;}
 private function performance(DashboardSummary $summary):int{Cache::forget(DashboardSummary::key(1));$a=microtime(true);$summary->get(1);$miss=(microtime(true)-$a)*1000;$a=microtime(true);$summary->get(1);$hit=(microtime(true)-$a)*1000;$this->table(['sample','milliseconds'],[['cache miss',round($miss,2)],['cache hit',round($hit,2)]]);$this->line('Compare relative samples; exact time is intentionally not asserted.');return self::SUCCESS;}
 private function incident():int{$this->table(['boundary','evidence'],[['database tickets',Ticket::count()],['queue ready',DB::table('jobs')->count()],['failed jobs',DB::table('failed_jobs')->count()],['delivery outcomes',IntegrationDelivery::selectRaw('status, count(*) as total')->groupBy('status')->pluck('total','status')->toJson()]]);$this->line('Correlate request_id -> job_id -> correlation_id in JSON logs; this command does not identify the failing boundary.');return self::SUCCESS;} private function invalid():int{$this->error('Choose cache, queue, race, performance, or incident.');return self::INVALID;}}
